// /fairytaletest - the pack tests itself.
//
// USE A THROWAWAY TEST WORLD (creative, superflat is ideal). The boss tests spawn and kill every
// boss next to you, clear mobs around the test spot and turn mobGriefing off.
//
//   /fairytaletest              list the tests
//   /fairytaletest all          everything below, in order (takes a few minutes)
//   /fairytaletest items        every quest item and custom item exists, the custom recipes loaded
//   /fairytaletest sharing      the loot-sharing maths (gear copies, stack splits, "at least one")
//   /fairytaletest route        the 17 route bosses: spawn, kill, eye/crown piece, torn page, fanfare
//   /fairytaletest bosses       every other boss: spawns, dies, what it drops, counts for sharing
//   /fairytaletest scan         finds every creature with 150+ health in the whole pack
//   /fairytaletest crown        the King's Crown: health, armor, flight, Speed, Haste, removal
//   /fairytaletest eyes         an eye that didn't come from a boss crumbles
//   /fairytaletest stop         stop a test that's running
//
// Results show in chat and are written to logs/kubejs/server.log (lines start with [FairytaleTest]).

const FTT = { run: null }
const FTT_ARENA_OFFSET = 14     // bosses spawn this many blocks east of you
const FTT_DEATH_WAIT = 60       // ticks to wait after a kill for drops and death animations
const FTT_DRAGON_WAIT = 230     // the Ender Dragon's death animation is about 10 seconds

function fttLog(kind, msg) {
  let r = FTT.run
  let line = `${kind === 'pass' ? '✔' : kind === 'fail' ? '✘' : kind === 'warn' ? '!' : '•'} ${msg}`
  console.info(`[FairytaleTest] ${line}`)
  if (!r) return
  if (kind === 'pass') r.pass++
  if (kind === 'fail') { r.fail++; r.failures.push(msg) }
  if (kind === 'warn') { r.warn++; r.warnings.push(msg) }
  let p = r.server.getPlayer(r.name)
  if (!p) return
  // passes are only summarised in chat (the log has every line); failures and warnings show in full
  if (kind === 'fail') p.tell(Text.of(line).red())
  else if (kind === 'warn') p.tell(Text.of(line).gold())
  else if (kind === 'info') p.tell(Text.of(line).gray())
}

function fttBox(x, y, z, r) {
  try { return AABB.of(x - r, y - r, z - r, x + r, y + r, z + r) } catch (e) {}
  let C = Java.loadClass('net.minecraft.world.phys.AABB')
  return new C(x - r, y - r, z - r, x + r, y + r, z + r)
}

// ---------- the runner: steps run one after another, each says how many ticks to wait ----------
function fttStart(player, title, steps) {
  if (FTT.run) { player.tell(Text.of('A Fairytale test is already running. /fairytaletest stop to cancel it.').red()); return 0 }
  if (!player.isCreative()) { player.tell(Text.of('Run the tests in creative mode, in a throwaway test world.').red()); return 0 }
  let server = player.server
  FTT.run = { server: server, name: player.username, title: title, steps: steps, i: 0, pass: 0, fail: 0, warn: 0, failures: [], warnings: [], ctx: {} }
  server.runCommandSilent('gamerule mobGriefing false')
  server.runCommandSilent('gamerule doMobLoot true')
  player.tell(Text.of(`Fairytale test: ${title}. Results in chat and in logs/kubejs/server.log`).gold())
  console.info(`[FairytaleTest] ===== ${title} (by ${player.username}) =====`)
  fttNext()
  return 1
}
function fttNext() {
  let r = FTT.run
  if (!r) return
  let p = r.server.getPlayer(r.name)
  if (!p) { console.info('[FairytaleTest] tester left, stopping'); FTT.run = null; return }
  if (r.i >= r.steps.length) { fttFinish(); return }
  let step = r.steps[r.i++]
  let wait = 1
  try { wait = step(p, r.ctx) || 1 } catch (e) { fttLog('fail', `test step crashed: ${e}`) }
  r.server.scheduleInTicks(wait, () => fttNext())
}
function fttFinish() {
  let r = FTT.run
  FTT.run = null
  let p = r.server.getPlayer(r.name)
  let sum = `${r.title} finished: ${r.pass} passed, ${r.fail} failed, ${r.warn} warnings`
  console.info(`[FairytaleTest] ===== ${sum} =====`)
  r.failures.forEach(f => console.info(`[FairytaleTest] FAILED: ${f}`))
  r.warnings.forEach(w => console.info(`[FairytaleTest] WARNING: ${w}`))
  if (p) {
    p.tell(r.fail ? Text.of(sum).red() : Text.of(sum).green())
    if (r.fail || r.warn) p.tell(Text.of('Send logs/kubejs/server.log to check the details.').gray())
  }
}

