function fttItemSteps() {
  return [p => {
    fttLog('info', 'Checking items and recipes...')
    let missing = []
    let list = []
    try { list = FAIRYTALE_QUEST_ITEMS } catch (e) { fttLog('warn', 'quest item list not loaded (checks/quest_item_check.js)') }
    list.forEach(id => { let ok = false; try { ok = !Item.of(id).isEmpty() } catch (e) {} if (!ok) missing.push(id) })
    if (missing.length) fttLog('fail', `quest items missing from the game: ${missing.join(', ')}`)
    else fttLog('pass', `all ${list.length} quest items exist`)
    let bookMissing = FTT_BOOK_ITEMS.filter(id => { try { return Item.of(id).isEmpty() } catch (e) { return true } })
    if (bookMissing.length) fttLog('fail', `Adventure Book shows items that don't exist: ${bookMissing.join(', ')}`)
    else fttLog('pass', `all ${FTT_BOOK_ITEMS.length} Adventure Book items exist`)
    let bookNoRecipe = FTT_BOOK_RECIPES.filter(id => { try { return !p.server.recipeManager.byKey(id).isPresent() } catch (e) { return true } })
    if (bookNoRecipe.length) fttLog('fail', `Adventure Book recipe pages with no recipe: ${bookNoRecipe.join(', ')}`)
    else fttLog('pass', `all ${FTT_BOOK_RECIPES.length} Adventure Book recipes load`)
    let custom = ['kubejs:crown_band', 'kubejs:crown_jewel', 'kubejs:crown_crest', 'kubejs:crown_setting', 'kubejs:dragons_heart', 'kubejs:kings_crown']
    custom.forEach(id => { let ok = false; try { ok = !Item.of(id).isEmpty() } catch (e) {} fttLog(ok ? 'pass' : 'fail', `custom item ${id}`) })
    let rm = p.server.recipeManager
    let recipes = ['kubejs:kings_crown', 'kubejs:adventure_book']
    recipes.forEach(id => {
      let ok = false
      try { ok = rm.byKey(id).isPresent() } catch (e) { ok = null }
      if (ok === null) fttLog('warn', `couldn't look up recipe ${id}`)
      else fttLog(ok ? 'pass' : 'fail', `recipe ${id} loaded`)
    })
    // other mods' loot tables and tags the pack repairs (kubejs/data and recipes/mod_bug_fixes.js)
    try {
      let EMPTY = Java.loadClass('net.minecraft.world.level.storage.loot.LootTable').EMPTY
      let tables = ['irons_spellbooks:chests/citadel/citadel_tomes', 'irons_spellbooks:chests/catacombs/crypt_loot',
        'idas:chests/archmages_tower/archmages_tower', 'idas:chests/archmages_tower/archmages_tower_library',
        'idas:chests/archmages_tower/archmages_tower_treasure', 'naturalist:entities/tortoise']
      tables.forEach(id => {
        let t = p.server.lootData.getLootTable(id)
        fttLog(t && t !== EMPTY ? 'pass' : 'fail', `loot table ${id} loads`)
      })
    } catch (e) { fttLog('warn', `couldn't check loot tables: ${e}`) }
    // counted through Forge's live tag manager: KubeJS's tag-ingredient cache is empty after a reload finishes
    let FTT_FR = Java.loadClass('net.minecraftforge.registries.ForgeRegistries')
    let FTT_RL = Java.loadClass('net.minecraft.resources.ResourceLocation')
    ;['aether_redux:swet_jelly', 'farmersdelight:sweets', 'farmersdelight:snacks', 'diet:sugars'].forEach(tag => {
      let n = -1
      try {
        let mgr = FTT_FR.ITEMS.tags()
        let key = mgr.createTagKey(new FTT_RL(tag))
        n = mgr.isKnownTagName(key) ? mgr.getTag(key).size() : 0
      } catch (e) { fttLog('warn', `couldn't count tag ${tag}: ${e}`) }
      // Diet isn't in the pack, so diet:sugars only has to load (its entries come from food mods)
      let ok = tag == 'diet:sugars' ? n >= 0 : n > 0
      fttLog(ok ? 'pass' : 'fail', `tag ${tag} loads (${n} items)`)
    })
    // Resonarium gear (quest chapter 23) is smithed with no template, the way Deeper Darker designed it
    ;['forbidden_arcanus:aurum_chest_boat', 'forbidden_arcanus:edelwood_chest_boat',
      'deeperdarker:resonarium_helmet_smithing', 'deeperdarker:resonarium_chestplate_smithing',
      'deeperdarker:resonarium_pickaxe_smithing', 'deeperdarker:resonarium_sword_smithing',
      'kubejs:ars_bond/inscription_table', 'kubejs:ars_bond/scroll_forge', 'kubejs:ars_bond/imbue_arcane_essence',
      'kubejs:ars_bond/fire_rune', 'kubejs:ars_bond/ender_rune', 'ars_nouveau:apprentice_spell_book_upgrade',
      'ars_nouveau:archmage_spell_book_upgrade',
      'kubejs:guide_books/fishing_journal', 'kubejs:guide_books/book_of_shadows', 'irons_spellbooks:patchouli_book',
      'ars_nouveau:worn_notebook', 'productivebees:guide_book', 'apotheosis:book', 'tconstruct:common/materials_and_you',
      'iceandfire:bestiary', 'alexsmobs:animal_dictionary'].forEach(id => {
      let ok = false
      try { ok = rm.byKey(id).isPresent() } catch (e) {}
      fttLog(ok ? 'pass' : 'fail', `recipe ${id} loaded`)
    })
    // every recipe that makes an End Remastered eye should be gone
    try {
      let eyeRecipes = 0
      rm.getRecipes().forEach(rec => {
        let out = ''
        try { out = String(rec.getResultItem(p.server.registryAccess()).id) } catch (e) {}
        if (/^endrem:[a-z_]+_eye$/.test(out)) eyeRecipes++
      })
      fttLog(eyeRecipes ? 'fail' : 'pass', eyeRecipes ? `${eyeRecipes} recipes still make End Remastered eyes` : 'no recipe makes an End Remastered eye')
    } catch (e) { fttLog('warn', `couldn't scan recipes for eyes: ${e}`) }
    fttInsaniumGear(p, rm)
    fttWorkstations()
    fttStaffs(rm)
    return 2
  }]
}

// Essence staffs (recipes/essence_staffs.js + startup_scripts/balance/weapon_and_armor_buffs.js):
// craftable, real melee and spell stats, and Iron's Spells sees their spell slots
function fttStaffs(rm) {
  let staffs = global.fairytaleStaffs
  if (!staffs) { fttLog('fail', 'staff stats not loaded (startup_scripts/balance/weapon_and_armor_buffs.js)'); return }
  ;['inferium', 'prudentium', 'tertium', 'imperium', 'supremium', 'awakened_supremium'].forEach(t => {
    let id = `kubejs:mystical/staff/${t}_staff`
    fttLog(rm.byKey(id).isPresent() ? 'pass' : 'fail', `recipe ${id} loaded`)
  })
  try {
    let SLOT = Java.loadClass('net.minecraft.world.entity.EquipmentSlot')
    let ATTR = Java.loadClass('net.minecraft.world.entity.ai.attributes.Attributes')
    let ISC = Java.loadClass('io.redspace.ironsspellbooks.api.spells.ISpellContainer')
    let IUtils = Java.loadClass('io.redspace.ironsspellbooks.api.util.Utils')
    Object.keys(staffs).forEach(id => {
      let stack = Item.of(id)
      let mods = stack.getAttributeModifiers(SLOT.MAINHAND)
      let dmg = 0
      let it = mods.get(ATTR.ATTACK_DAMAGE).iterator()
      while (it.hasNext()) dmg += it.next().getAmount()
      let names = []
      let kit = mods.keySet().iterator()
      while (kit.hasNext()) names.push(String(kit.next().getDescriptionId()))
      let spell = names.some(n => n.indexOf('spell_power') >= 0)
      global.fairytaleStaffSlots(stack)
      let slots = ISC.isSpellContainer(stack) ? ISC.get(stack).getMaxSpellCount() : 0
      let imbue = IUtils.canImbue(stack)
      let ok = dmg >= staffs[id].damage && spell && slots == staffs[id].slots && imbue
      fttLog(ok ? 'pass' : 'fail', `${id}: ${dmg + 1} damage, spell power ${spell ? 'yes' : 'no'}, ${slots} spell slots, Arcane Anvil ${imbue ? 'accepts' : 'refuses'} it`)
    })
  } catch (e) { fttLog('fail', `staff check crashed: ${e}`) }
}

// Visual Workbench gives the crafting table a block entity that keeps (and shows) its items;
// Apotheosis owns the enchanting table and the anvils (why Easy Magic / Easy Anvils were removed)
function fttWorkstations() {
  try {
    let BLOCKS = Java.loadClass('net.minecraft.world.level.block.Blocks')
    let POS = Java.loadClass('net.minecraft.core.BlockPos')
    let table = BLOCKS.CRAFTING_TABLE
    let be = null
    try { be = table.newBlockEntity(POS.ZERO, table.defaultBlockState()) } catch (e) {}
    let name = be ? String(be.getClass().getName()) : 'none'
    fttLog(name.indexOf('visualworkbench') >= 0 ? 'pass' : 'fail', `crafting table keeps its items (Visual Workbench): block entity ${name}`)
    ;[['enchanting table', BLOCKS.ENCHANTING_TABLE], ['anvil', BLOCKS.ANVIL]].forEach(b => {
      let cls = String(b[1].getClass().getName())
      fttLog(cls.indexOf('apotheosis') >= 0 ? 'pass' : 'warn', `${b[0]} is Apotheosis's (${cls})`)
    })
  } catch (e) { fttLog('warn', `couldn't check the crafting table / enchanting table / anvil: ${e}`) }
}

// Insanium gear (recipes/insanium_gear.js): the recipes are there, Mystical Adaptations' own are gone,
// and an upgraded piece keeps its enchantments, name and quality-style attributes with the new base stats
function fttInsaniumGear(p, rm) {
  let ups = null
  try { ups = FT_IG_UPGRADES } catch (e) {}
  if (!ups) { fttLog('fail', 'Insanium gear script not loaded (recipes/insanium_gear.js)'); return }
  let missing = ups.filter(u => !rm.byKey('kubejs:insanium_gear/' + u[1].split(':')[1]).isPresent())
  fttLog(missing.length ? 'fail' : 'pass', missing.length ? `Insanium upgrades missing: ${missing.map(u => u[1]).join(', ')}`
    : `all ${ups.length} Insanium upgrade recipes load`)
  let leftover = ups.filter(u => u[1] != 'mysticaladaptations:insanium_paxel' && rm.byKey(u[1]).isPresent())
  fttLog(leftover.length ? 'fail' : 'pass', leftover.length ? `Mystical Adaptations upgrades that lose enchantments are still there: ${leftover.map(u => u[1]).join(', ')}`
    : 'Mystical Adaptations\' own upgrade recipes are replaced')
  ;['kubejs:insanium_gear/insanium_reprocessor', 'kubejs:mystical/insanium_essence'].forEach(id => {
    fttLog(rm.byKey(id).isPresent() ? 'pass' : 'fail', `recipe ${id} loaded`)
  })
  try {
    let SLOT = Java.loadClass('net.minecraft.world.entity.EquipmentSlot')
    let ATTR = Java.loadClass('net.minecraft.world.entity.ai.attributes.Attributes')
    let MOD = Java.loadClass('net.minecraft.world.entity.ai.attributes.AttributeModifier')
    let OP = Java.loadClass('net.minecraft.world.entity.ai.attributes.AttributeModifier$Operation')
    let COMP = Java.loadClass('net.minecraft.network.chat.Component')
    let UUID = Java.loadClass('java.util.UUID')
    let oldId = 'mysticalagriculture:awakened_supremium_chestplate'
    let newId = 'mysticaladaptations:insanium_chestplate'
    let armorOf = (stack) => {
      let sum = 0
      let it = stack.getAttributeModifiers(SLOT.CHEST).get(ATTR.ARMOR).iterator()
      while (it.hasNext()) { let m = it.next(); if (m.getOperation() == OP.ADDITION) sum += m.getAmount() }
      return sum
    }
    let plain = Item.of(newId)
    let base = Item.of(oldId)
    let CTAG = Java.loadClass('net.minecraft.nbt.CompoundTag')
    let LTAG = Java.loadClass('net.minecraft.nbt.ListTag')
    let ench = new CTAG()
    ench.putString('id', 'minecraft:protection')
    ench.putShort('lvl', 4)
    let enchList = new LTAG()
    enchList.add(ench)
    base.getOrCreateTag().put('Enchantments', enchList)
    base.setHoverName(COMP.literal('Test Plate'))
    let up = ftIgUpgrade(base, oldId, newId)
    let kept = String(up.id) == newId && up.getEnchantmentTags().size() == 1 && String(up.getHoverName().getString()) == 'Test Plate'
    fttLog(kept ? 'pass' : 'fail', `upgraded chestplate keeps its enchantment and name (${up.id}, ${up.getEnchantmentTags().size()} enchantments, "${up.getHoverName().getString()}")`)
    let same = Math.abs(armorOf(up) - armorOf(plain)) < 0.01
    fttLog(same ? 'pass' : 'fail', `upgraded chestplate has Insanium armor: ${armorOf(up)} (a new one has ${armorOf(plain)})`)
    // a piece whose attributes are written into its NBT (old base stats + one extra +1 armor)
    let nbt = Item.of(oldId)
    let it = global.ftIgItemMods(nbt, SLOT.CHEST).entries().iterator()
    let defaults = []
    while (it.hasNext()) { let e = it.next(); defaults.push([e.getKey(), e.getValue()]) }
    defaults.forEach(d => nbt.addAttributeModifier(d[0], d[1], SLOT.CHEST))
    nbt.addAttributeModifier(ATTR.ARMOR, new MOD(UUID.fromString('fa17e000-0000-4000-8000-0000000000aa'), 'test quality', 1.0, OP.ADDITION), SLOT.CHEST)
    let up2 = ftIgUpgrade(nbt, oldId, newId)
    let ok2 = Math.abs(armorOf(up2) - (armorOf(plain) + 1)) < 0.01
    fttLog(ok2 ? 'pass' : 'fail', `upgraded chestplate with NBT attributes: ${armorOf(up2)} armor (expected ${armorOf(plain) + 1}: Insanium base + the extra 1)`)
  } catch (e) { fttLog('fail', `Insanium upgrade check crashed: ${e}`) }
}

// ---------- loot sharing maths ----------
function fttSharingSteps() {
  return [p => {
    fttLog('info', 'Checking the loot-sharing rules...')
    let S = global.fairytaleSplitPlan
    if (!S) { fttLog('fail', 'loot sharing script not loaded'); return 1 }
    let cases = [
      ['7 bones between 2', S(7, true, 2, 0), [4, 3]],
      ['7 bones between 3', S(7, true, 3, 0), [3, 2, 2]],
      ['1 Nether Star between 2 (everyone gets one)', S(1, true, 2, 0), [1, 1]],
      ['a sword between 3 (everyone gets a copy)', S(1, false, 3, 0), [1, 1, 1]],
      ['64 arrows between 4', S(64, true, 4, 0), [16, 16, 16, 16]]
    ]
    cases.forEach(c => fttLog(String(c[1]) === String(c[2]) ? 'pass' : 'fail', `${c[0]}: ${c[1]} (expected ${c[2]})`))
    let M = global.fairytaleIsMajor
    if (M) {
      let fake = (type, hp, tame) => ({ type: type, maxHealth: hp, isPlayer: () => false, isTame: () => !!tame })
      let rules = [
        ['the Wither counts as a boss', M(fake('minecraft:wither', 300)), true],
        ['the Ender Dragon counts as a boss', M(fake('minecraft:ender_dragon', 200)), true],
        ['an unlisted 400-health creature counts', M(fake('somemod:new_boss', 400)), true],
        ['a zombie does not count', M(fake('minecraft:zombie', 20)), false],
        ["a tamed pet does not count", M(fake('somemod:pet', 500, true)), false]
      ]
      rules.forEach(c => fttLog(c[1] === c[2] ? 'pass' : 'fail', c[0]))
    }
    fttLog('info', 'Real sharing between players needs 2 people: see the checklist.')
    return 2
  }]
}

// ---------- boss kill tests ----------
// one boss = three steps: spawn, kill, collect what it dropped
function fttBossSteps(id, label, route) {
  let st = {}
  return [
    (p, ctx) => {
      st.x = p.x + FTT_ARENA_OFFSET; st.y = p.y; st.z = p.z
      st.before = route ? p.inventory.count(route.reward) : 0
      let e = null
      try { e = p.level.createEntity(id) } catch (err) { e = null }
      if (!e) { fttLog('fail', `${label} (${id}): this creature doesn't exist in the pack`); st.skip = true; return 1 }
      e.setPosition(st.x, st.y, st.z)
      e.spawn()
      st.e = e
      return 10
    },
    (p, ctx) => {
      if (st.skip) return 1
      let e = st.e
      if (!e.isAlive()) { fttLog('warn', `${label}: disappeared by itself before it could be killed (may only exist in its own structure or dimension)`); st.skip = true; return 1 }
      st.major = global.fairytaleIsMajor ? global.fairytaleIsMajor(e) : false
      // count the tester as having fought it, then deal a killing player hit
      let pd = e.persistentData
      let hits = pd.getCompound('fairytale_hits')
      hits.putFloat(p.getStringUuid(), e.maxHealth)
      pd.put('fairytale_hits', hits)
      st.killedBy = 'player hit'
      let dragon = id === 'minecraft:ender_dragon'
      if (!dragon) { try { e.setHealth(1) } catch (err) {} }
      // a real player hit, the way /damage does it, so player-kill loot and the route reward both apply
      p.server.runCommandSilent(`damage ${e.uuid} 1000000 minecraft:player_attack by ${p.username}`)
      // the dragon doesn't die on the spot: it drops to 1 health and plays its 10-second death scene.
      // Never /kill it after a hit landed: on the dragon /kill just deletes it, with no death and no reward.
      if (dragon && e.getHealth() <= 1) return FTT_DRAGON_WAIT
      // bosses that fight in several bodies (Sir Pumpkinhead): finish off each new form as it appears
      let group = global.fairytaleRouteGroup ? global.fairytaleRouteGroup(id) : null
      if (group) {
        ;[10, 25, 40].forEach(t => p.server.scheduleInTicks(t, () => {
          p.level.getEntitiesWithin(fttBox(st.x, st.y, st.z, 40)).forEach(f => {
            if (!group.re.test(String(f.type))) return
            try { if (f.isLiving() && f.isAlive()) p.server.runCommandSilent(`damage ${f.uuid} 1000000 minecraft:player_attack by ${p.username}`) } catch (err) {}
          })
        }))
      }
      if (dragon) st.killedBy = '/kill (the hit did not land; /kill gives the dragon no death, so no reward)'
      if (e.isAlive()) {
        e.kill()
        if (!dragon) st.killedBy = '/kill (ignored normal damage)'
        // bosses that change phase or play a death scene sometimes need a second try
        ;[20, 40].forEach(t => p.server.scheduleInTicks(t, () => { if (e.isAlive()) e.kill() }))
      }
      return id === 'minecraft:ender_dragon' ? FTT_DRAGON_WAIT : (group ? FTT_DEATH_WAIT + 60 : FTT_DEATH_WAIT)
    },
    (p, ctx) => {
      if (st.skip) return 1
      let e = st.e
      if (e.isAlive()) { fttLog('warn', `${label}: ignored both damage and /kill (a phase or cutscene boss); fight it by hand to check its drops`); e.discard(); return 1 }
      // what it dropped
      let found = {}
      let n = 0
      p.level.getEntitiesWithin(fttBox(st.x, st.y, st.z, 28)).forEach(ent => {
        if (String(ent.type) !== 'minecraft:item') return
        let s = ent.item
        let k = String(s.id)
        found[k] = (found[k] || 0) + s.count
        n++
        ent.discard()
      })
      let drops = Object.keys(found).map(k => `${found[k]}x ${k}`).join(', ')
      let how = st.killedBy === 'player hit' ? '' : ` [${st.killedBy}: loot that needs a player kill may be missing]`
      fttLog(n ? 'pass' : 'warn', `${label}: died${how}; drops: ${drops || 'nothing'}`)
      if (!st.major) fttLog('fail', `${label}: does NOT count as a boss for loot sharing`)
      if (route) {
        let after = p.inventory.count(route.reward)
        fttLog(after > st.before ? 'pass' : 'fail', `${label}: gave ${route.reward}`)
        let page = false
        try { page = p.isAdvancementDone(`kubejs:fairytale/${route.page}`) } catch (err) {}
        fttLog(page ? 'pass' : 'fail', `${label}: unlocked torn page ${route.page}`)
      }
      // clear leftovers (minions, clones, xp) around the test spot
      p.server.runCommandSilent(`execute positioned ${st.x} ${st.y} ${st.z} run kill @e[type=!minecraft:player,distance=..40]`)
      return 5
    }
  ]
}

function fttRouteList() {
  let out = []
  try {
    Object.keys(ROUTE).forEach(id => {
      let info = ROUTE[id]
      if (id === 'born_in_chaos_v1:sir_pumpkinhead_without_horse') return   // same page as the mounted one
      out.push([id, info.name, info])
    })
  } catch (e) { fttLog('fail', 'boss route script not loaded (story/boss_route_pages_and_loot.js)') }
  return out
}
function fttRouteSteps() {
  let steps = [p => { fttLog('info', 'Route bosses: spawning and killing each one next to you...'); return 1 }]
  fttRouteList().forEach(b => { steps = steps.concat(fttBossSteps(b[0], b[1], b[2])) })
  return steps
}

// every creature with 150+ max health, read straight from the game's creature list
function fttScanBig(level) {
  let out = []
  let reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries').ENTITY_TYPE
  reg.keySet().forEach(rl => {
    let id = String(rl)
    let e = null
    try { e = reg.get(rl).create(level) } catch (err) { e = null }
    if (!e) return
    let hp = 0
    try { if (e.isLiving()) hp = e.maxHealth } catch (err) {}
    if (hp >= 150) out.push([id, hp])
    try { e.discard() } catch (err) {}
  })
  return out.sort((a, b) => b[1] - a[1])
}
function fttScanSteps() {
  return [p => {
    fttLog('info', 'Scanning every creature in the pack for 150+ health...')
    let big = []
    try { big = fttScanBig(p.level) } catch (e) { fttLog('warn', `scan failed: ${e}`); return 1 }
    big.forEach(b => fttLog('info', `big creature: ${b[0]} (${b[1]} health) - shares loot`))
    fttLog('pass', `${big.length} creatures with 150+ health found; all of them share their loot`)
    return 1
  }]
}
function fttBossesSteps() {
  let steps = [p => { fttLog('info', 'Other bosses: spawning and killing each one next to you...'); return 1 }]
  // the listed bosses plus every big creature the scan finds, minus the route bosses (tested separately)
  steps.push((p, ctx) => {
    let ids = {}
    try { OTHER_BOSSES.forEach(id => ids[id] = id) } catch (e) {}
    try { fttScanBig(p.level).forEach(b => ids[b[0]] = b[0]) } catch (e) { fttLog('warn', `scan failed: ${e}`) }
    try { Object.keys(ROUTE).forEach(id => delete ids[id]) } catch (e) {}
    let more = []
    Object.keys(ids).sort().forEach(id => { more = more.concat(fttBossSteps(id, id, null)) })
    // splice the boss steps in right after this one
    let r = FTT.run
    r.steps = r.steps.slice(0, r.i).concat(more, r.steps.slice(r.i))
    fttLog('info', `${Object.keys(ids).length} bosses and big creatures to test`)
    return 1
  })
  return steps
}

// ---------- King's Crown (runs in survival for a few seconds) ----------
function fttCrownSteps() {
  let st = {}
  return [
    p => {
      fttLog('info', 'King\'s Crown: switching you to survival for a few seconds...')
      st.helmet = p.headArmorItem.copy()
      p.setHeadArmorItem(Item.of('minecraft:air'))
      p.server.runCommandSilent(`gamemode survival ${p.username}`)
      return 25
    },
    p => {
      st.hp = p.maxHealth
      st.armor = p.getArmorValue()
      p.setHeadArmorItem(Item.of('kubejs:kings_crown', '{Unbreakable:1b}'))
      return 30
    },
    p => {
      fttLog(p.maxHealth >= st.hp + 40 ? 'pass' : 'fail', `crown: max health ${st.hp} -> ${p.maxHealth} (+20 hearts expected)`)
      fttLog(p.getArmorValue() >= st.armor + 30 ? 'pass' : 'fail', `crown: armor ${st.armor} -> ${p.getArmorValue()} (+30 expected)`)
      fttLog(p.abilities.mayfly ? 'pass' : 'fail', 'crown: flight turned on')
      fttLog(p.potionEffects.isActive('minecraft:speed') ? 'pass' : 'fail', 'crown: Speed')
      fttLog(p.potionEffects.isActive('minecraft:haste') ? 'pass' : 'fail', 'crown: Haste')
      let h = p.headArmorItem
      let unb = false
      try { unb = h.nbt.getBoolean('Unbreakable') } catch (e) {}
      fttLog(unb ? 'pass' : 'fail', 'crown: unbreakable')
      p.setHeadArmorItem(Item.of('minecraft:air'))
      return 30
    },
    p => {
      fttLog(!p.abilities.mayfly ? 'pass' : 'fail', 'crown removed: flight turned off')
      fttLog(!p.potionEffects.isActive('minecraft:speed') ? 'pass' : 'fail', 'crown removed: Speed gone')
      fttLog(p.maxHealth <= st.hp ? 'pass' : 'fail', `crown removed: max health back to ${p.maxHealth}`)
      p.setHeadArmorItem(st.helmet)
      p.server.runCommandSilent(`gamemode creative ${p.username}`)
      return 2
    }
  ]
}

// ---------- fake eyes crumble (survival) ----------
function fttEyeSteps() {
  let st = {}
  return [
    p => {
      fttLog('info', 'Eyes: checking a non-boss eye crumbles...')
      p.server.runCommandSilent(`gamemode survival ${p.username}`)
      return 5
    },
    p => {
      st.before = p.inventory.count('endrem:old_eye')
      p.give(Item.of('endrem:old_eye'))
      return 10
    },
    p => {
      let after = p.inventory.count('endrem:old_eye')
      fttLog(after === st.before ? 'pass' : 'fail', after === st.before ? 'an eye that didn\'t come from a boss crumbled' : 'a non-boss eye was NOT removed')
      p.server.runCommandSilent(`gamemode creative ${p.username}`)
      return 2
    }
  ]
}

const FTT_TESTS = {
  items: ['items and recipes', fttItemSteps],
  sharing: ['loot sharing rules', fttSharingSteps],
  route: ['route bosses', fttRouteSteps],
  bosses: ['all other bosses', fttBossesSteps],
  scan: ['big creature scan', fttScanSteps],
  crown: ["King's Crown", fttCrownSteps],
  eyes: ['eye clean-up', fttEyeSteps]
}

ServerEvents.commandRegistry(event => {
  let { commands: Commands } = event
  let cmd = Commands.literal('fairytaletest').requires(s => s.hasPermission(2))
    .executes(ctx => {
      let p = ctx.source.playerOrException
      p.tell(Text.of('Fairytale tests (use a throwaway creative test world):').gold())
      p.tell(Text.of('/fairytaletest all | items | sharing | route | bosses | scan | crown | eyes | stop').gray())
      return 1
    })
    .then(Commands.literal('stop').executes(ctx => {
      if (FTT.run) { FTT.run = null; ctx.source.playerOrException.tell(Text.of('Fairytale test stopped.').gold()) }
      return 1
    }))
    .then(Commands.literal('all').executes(ctx => {
      let steps = []
      ;['items', 'sharing', 'crown', 'eyes', 'route', 'bosses'].forEach(k => { steps = steps.concat(FTT_TESTS[k][1]()) })
      return fttStart(ctx.source.playerOrException, 'all tests', steps)
    }))
  Object.keys(FTT_TESTS).forEach(k => {
    cmd = cmd.then(Commands.literal(k).executes(ctx => fttStart(ctx.source.playerOrException, FTT_TESTS[k][0], FTT_TESTS[k][1]())))
  })
  event.register(cmd)
})
